Condition = [\n    // Check if the browser language is Chinese\n    navigator.languages.includes('zh') || navigator.languages.includes('zh-CN'),\n    // Check if the URL path ends with -cn\n    /-cn\\/?$/.test(window.location.pathname),\n    // chinese mirror URL\n    !['ant-design.gitee.io', new URL(officialChinaMirror).hostname].includes(\n      window.location.hostname,\n    ),\n    // PR review URL\n    !window.location.host.includes('surge'),\n    // development mode\n    !['127.0.0.1', 'localhost'].includes(window.location.hostname),\n  ];\n\n  const isEnabled = always || enabledCondition.every(Boolean);\n\n  if (!isEnabled) {\n    return;\n  }\n\n  const prefixCls = 'antd-mirror-notify';\n  const primaryColor = '#1677ff';\n\n  function insertCss() {\n    const style = document.createElement('style');\n    style.innerHTML = `\n    @keyframes slideInRight {\n      from {\n        transform: translate3d(100%, 0, 0);\n        visibility: visible;\n      }\n\n      to {\n        transform: translate3d(0, 0, 0);\n      }\n    }\n\n    .${prefixCls} {\n      position: fixed;\n      inset-inline-end: 12px;\n      inset-block-start: 12px;\n      z-index: 9999;\n      width: 360px;\n      background-color: #fff;\n      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\n      border-radius: 4px;\n      overflow: hidden;\n      animation: slideInRight 0.3s ease-in-out;\n    }\n    .${prefixCls}-content {\n      padding: 16px;\n    }\n    .${prefixCls}-content a {\n      color: ${primaryColor};\n      text-decoration: none;\n      &:hover {\n        text-decoration: underline;\n      }\n    }\n    .${prefixCls}-title {\n      font-size: 16px;\n      font-weight: bold;\n      margin-block-end: 8px;\n    }\n    .${prefixCls}-message {\n      font-size: 14px;\n      color: #555;\n      line-height: 1.57;\n    }\n    .${prefixCls}-footer {\n      display: none;\n      margin-block-start: 16px;\n      justify-content: flex-end;\n     }\n\n    .${prefixCls}-progress {\n      position: relative;\n      inset-inline-end: 0;\n      width: 100%;\n      height: 4px;\n      background-color: #f0f0f0;\n      border-radius: 2px;\n      overflow: hidden;\n    }\n\n    .${prefixCls}-progress::after {\n      content: '';\n      position: absolute;\n      top: 0;\n      inset-inline-start: 0;\n      height: 100%;\n      width: var(--progress, 0%);\n      background-color: ${primaryColor};\n      transition: width 0.05s linear; /* Adjusted for smoother animation matching refreshRate */\n    }\n    .${prefixCls}-close {\n      all: unset;\n      position: absolute;\n      inset-inline-end: 2px;\n      inset-block-start: 2px;\n      width: 32px;\n      height: 32px;\n      font-size: 16px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: #999;\n      cursor: pointer;\n    }\n\n    .${prefixCls}-close:hover {\n      color: #333;\n    }\n\n    .${prefixCls}-action {\n      all: unset;\n      display: inline-block;\n      padding: 4px 8px;\n      background-color: ${primaryColor};\n      color: #fff;\n      border-radius: 4px;\n      text-align: center;\n      cursor: pointer;\n      font-size: 14px;\n    }\n  `;\n\n    document.head.append(style);\n  }\n\n  function createNotification() {\n    insertCss();\n\n    const notify = document.createElement('div');\n    notify.className = `${prefixCls} slideInRight`;\n    notify.innerHTML = `\n    <div class=\"${prefixCls}-content\">\n      <div class=\"${prefixCls}-title\">🇨🇳 访问不畅？试试国内镜像</div>\n      <div class=\"${prefixCls}-message\">\n        国内镜像站点可以帮助您更快地访问文档和资源。<br>\n        请尝试访问 <a class=\"${prefixCls}-link\" href=\"${officialChinaMirror}\">国内镜像站点</a>，以获得更好的体验。\n      </div>\n      <div class=\"${prefixCls}-footer\">\n        <button class=\"${prefixCls}-action ${prefixCls}-link\">🚀 立即前往</button>\n      </div>\n    </div>\n    <button class=\"${prefixCls}-close\">X</button>\n    <div class=\"${prefixCls}-progress\" style=\"--progress: 100%;\"></div>\n    `;\n    document.body.appendChild(notify);\n\n    notify.querySelector(`.${prefixCls}-close`).addEventListener('click', () => {\n      removeNotify();\n    });\n\n    const goToChinaMirror = (event) => {\n      event.preventDefault();\n      if (window.gtag) {\n        window.gtag('event', '点击', {\n          event_category: '前往国内镜像',\n          event_label: officialChinaMirror,\n        });\n      }\n      window.location.href = officialChinaMirror;\n      removeNotify();\n    };\n\n    notify.querySelectorAll(`.${prefixCls}-link`).forEach((link) => {\n      link.addEventListener('click', goToChinaMirror);\n    });\n\n    const refreshRate = 50; // ms\n    const duration = 10; // s\n    const step = 100 / ((duration * 1000) / refreshRate);\n    let progressInterval = -1;\n\n    function removeNotify() {\n      clearInterval(progressInterval);\n      notify.remove();\n    }\n\n    const progressEl = notify.querySelector(`.${prefixCls}-progress`);\n    let currentProgressValue = 100;\n\n    const progress = {\n      get value() {\n        return currentProgressValue;\n      },\n      set value(val) {\n        currentProgressValue = Math.max(0, Math.min(100, val));\n        progressEl.style.setProperty('--progress', `${currentProgressValue}%`);\n      },\n    };\n\n    function startProgressTimer() {\n      if (progressInterval !== -1) {\n        clearInterval(progressInterval);\n      }\n      progressInterval = setInterval(() => {\n        if (progress.value <= 0) {\n          removeNotify();\n        } else {\n          progress.value -= step;\n        }\n      }, refreshRate);\n    }\n\n    startProgressTimer();\n\n    notify.addEventListener('mouseenter', () => {\n      clearInterval(progressInterval);\n    });\n\n    notify.addEventListener('mouseleave', () => {\n      startProgressTimer();\n    });\n  }\n\n  function checkMirrorAvailable(timeout = 1500) {\n    return new Promise((resolve) => {\n      const img = new Image();\n      let done = false;\n      img.onload = () => {\n        if (!done) {\n          done = true;\n          resolve(true);\n        }\n      };\n      img.onerror = () => {\n        if (!done) {\n          done = true;\n          resolve(false);\n        }\n      };\n      img.src = new URL('/llms.txt', officialChinaMirror).href;\n      setTimeout(() => {\n        if (!done) {\n          done = true;\n          resolve(false);\n        }\n      }, timeout);\n    });\n  }\n\n  // 断定网络不畅阈值（秒）\n  const delayDuration = 3;\n\n  const reactTimeoutId = setTimeout(() => {\n    if (typeof window[SIGN]?.YES === 'undefined') {\n      console.error(\n        `antd.mirror-notify: 页面加载超过 ${delayDuration} 秒，可能是网络不畅。\\n请尝试访问国内镜像站点。%c${officialChinaMirror}`,\n        `color: ${primaryColor}; font-weight: bold;`,\n      );\n      checkMirrorAvailable().then((isFast) => {\n        if (isFast) {\n          createNotification();\n        }\n      });\n    }\n  }, delayDuration * 1000);\n\n  // 交给 React effect 清理\n  window[SIGN] = function stopMirrorNotify() {\n    window[SIGN].YES = Date.now();\n    clearTimeout(reactTimeoutId);\n  };\n})();\n"},{"async":true,"content":"/* eslint-disable */\n// https://clarity.microsoft.com\n(function (c, l, a, r, i, t, y) {\n  c[a] =\n    c[a] ||\n    function () {\n      (c[a].q = c[a].q || []).push(arguments);\n    };\n  t = l.createElement(r);\n  t.async = 1;\n  t.src = 'https://www.clarity.ms/tag/' + i;\n  y = l.getElementsByTagName(r)[0];\n  y.parentNode.insertBefore(t, y);\n})(window, document, 'clarity', 'script', 'lyia7jfwui');\n"},{"async":true,"content":"(() => {\n  if (!('modelContext' in navigator)) {\n    return;\n  }\n  const mc = navigator.modelContext;\n\n  const controller = new AbortController();\n\n  mc.registerTool(\n    {\n      name: 'search-antd-docs',\n      description: 'Search Ant Design component documentation and return relevant results.',\n      inputSchema: {\n        type: 'object',\n        properties: {\n          query: {\n            type: 'string',\n            description: 'The search query for Ant Design documentation.',\n          },\n        },\n        required: ['query'],\n      },\n    },\n    (input) => ({\n      content: [\n        {\n          type: 'text',\n          text: `Search Ant Design docs at: https://ant.design/components/overview. Query: ${input.query}`,\n        },\n      ],\n    }),\n    { signal: controller.signal },\n  );\n})();\n"}]}; window.__UMI_BUILD_ClIENT_CSS__ = ["/_dumi_global_less_19mmnhuljhj8q.445d9ff6.css","/node_modules_dumi_theme-default_builtins_Badge_index_less_0jtu9e4jtjh-z.a11d0fc4.css","/_088894drf7-ll.4fb5706e.css","/components_style_~antd_layer_0kf97_4fxi09j.1c487811.css","/node_modules__xyflow_react_dist_style_1x1vxi3blmbf7.78c792ee.css","/node_modules_dumi_theme-default_slots_1d9sx1nulbpfh.da1e248f.css","/node_modules_dumi_dist_client_pages_Demo_index_less_16ypac1iyycde.1b71f02f.css"]</script><script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script><script async="">(function createMirrorModal() {
  const SIGN = Symbol.for('antd.mirror-notify');
  const always = window.localStorage.getItem('DEBUG') === 'antd';
  const officialChinaMirror = 'https://ant-design.antgroup.com?utm_source=mirror-notify';

  const enabledCondition = [
    // Check if the browser language is Chinese
    navigator.languages.includes('zh') || navigator.languages.includes('zh-CN'),
    // Check if the URL path ends with -cn
    /-cn\/?$/.test(window.location.pathname),
    // chinese mirror URL
    !['ant-design.gitee.io', new URL(officialChinaMirror).hostname].includes(
      window.location.hostname,
    ),
    // PR review URL
